    {
      "rank": 1,
      "ballot_id": "B011",
      "proposed_laureates": ["Charles L. Bennett", "Lyman A. Page Jr."],
      "assessment": {
        "nobel_worthiness": "WMAP made precision measurements of the cosmic microwave background that established a quantitative picture of the universe's age, composition, and evolution. This is a major, experimentally grounded advance in cosmology.",
        "attribution": "Bennett and Page represent leadership in the mission and its central measurement work; Spergel's contribution to cosmological interpretation is substantial, so the boundary between measurement and interpretation deserves careful review.",
        "maturity": "The observations and their cosmological consequences have been tested against later measurements and independent evidence over many years.",
        "uncertainties": ["The laureate limit requires distinguishing the mission's experimental leadership from the wider team and the theoretical interpretation."]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": ["Alexei Kitaev", "Andrew M. Steane", "Peter W. Shor"],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected despite the fragility of quantum states, making scalable quantum computation physically conceivable and shaping experimental quantum science.",
        "attribution": "Kitaev, Steane, and Shor made distinct foundational contributions to topological and code-based approaches; their work should be assessed as complementary original inventions.",
        "maturity": "The principles are experimentally demonstrated across platforms, though large fault-tolerant machines remain a work in progress.",
        "uncertainties": ["The eventual practical reach of fault-tolerant quantum computing is unsettled, but the conceptual advance is already clear."]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B035",
      "proposed_laureates": ["Eli Yablonovitch", "Sajeev John"],
      "assessment": {
        "nobel_worthiness": "The proposal and realization of photonic band gaps opened a powerful way to control light in structured materials, with lasting influence across optics and photonics.",
        "attribution": "Yablonovitch and John independently established the central idea; Joannopoulos helped develop and disseminate the field, and the original conceptual and experimental record should guide credit.",
        "maturity": "The physics is well established, with extensive experimental confirmation and broad use in photonic research.",
        "uncertainties": ["The precise balance of credit among the early independent proposals, demonstrations, and later development merits historical scrutiny."]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B025",
      "proposed_laureates": ["Claudio Pellegrini", "Kwang-Je Kim"],
      "assessment": {
        "nobel_worthiness": "X-ray free-electron lasers provide intense, ultrashort pulses that reveal matter at atomic and molecular scales, creating a transformative experimental capability.",
        "attribution": "Pellegrini and Kim are credited for central concepts in the facility's development; Rossbach's role and the contributions of the broader accelerator and facility teams require careful comparison.",
        "maturity": "Operating facilities have produced a large body of reproducible science, demonstrating the value of the instrument beyond its initial promise.",
        "uncertainties": ["Credit spans theory, accelerator design, construction, and first operation, making attribution among named individuals difficult."]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B021",
      "proposed_laureates": ["Hidetoshi Katori", "Jun Ye"],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have pushed precision timekeeping into a regime that enables new tests of fundamental physics and practical applications in measurement and navigation.",
        "attribution": "Katori and Ye are leading independent pioneers whose experimental work established the method and its high accuracy.",
        "maturity": "The technique is supported by repeated precision measurements and continuing independent improvements, though its full metrological role is still developing.",
        "uncertainties": ["The distinction between the original clock concept and subsequent demonstrations and refinements should be established from the experimental history."]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B004",
      "proposed_laureates": ["Immanuel Bloch", "Markus Greiner"],
      "assessment": {
        "nobel_worthiness": "Optical-lattice experiments made controlled quantum many-body systems accessible in the laboratory and enabled direct study of phenomena previously treated mainly through theory.",
        "attribution": "Bloch and Greiner led landmark experimental demonstrations; Cirac and Zoller supplied influential theoretical foundations, and the distinction between conceptual and experimental contributions matters.",
        "maturity": "The platform has been repeatedly verified and developed into a mature tool for studying quantum matter.",
        "uncertainties": ["Several groups and theoretical contributions were essential, so the specific discovery being recognized must be defined narrowly."]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B046",
      "proposed_laureates": ["Franz J. Giessibl", "Gerhard Meyer", "Leo Gross"],
      "assessment": {
        "nobel_worthiness": "qPlus force microscopy enabled atomic-scale imaging and spectroscopy with exceptional sensitivity, extending what can be measured on surfaces and individual molecules.",
        "attribution": "Giessibl pioneered the qPlus sensor; Meyer and Gross made important advances in its application and atomic-resolution imaging, so the prize citation would need to identify the original invention precisely.",
        "maturity": "The method is established in surface science and has produced reproducible atomic-scale measurements.",
        "uncertainties": ["The contribution of the sensor invention should be separated historically from later imaging and spectroscopy milestones."]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B002",
      "proposed_laureates": ["Charles H. Bennett", "Gilles Brassard", "Artur Ekert"],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution established a fundamental connection between quantum measurement and secure communication, and experiments have advanced it toward practical networks.",
        "attribution": "Bennett and Brassard introduced a foundational protocol, while Ekert proposed an influential entanglement-based approach; the title also includes global networks, whose development involves many later contributors.",
        "maturity": "Quantum key distribution is experimentally mature, but global quantum networks remain under development and their scale and long-term utility are not settled.",
        "uncertainties": ["The broad discovery label combines early protocols with a network goal that is still evolving; Pan's experimental role in later network demonstrations also complicates attribution."]
      }
    }
  ]
